<script setup lang="ts">import{onMounted}from'vue';import GroupCard from'../components/GroupCard.vue';import{useTournamentStore}from'../stores/tournament';const s=useTournamentStore();onMounted(()=>{s.connect();s.loadState();s.loadTournament()})</script>
<template><div class="public-page"><header class="public-hero"><div class="cup">🏆</div><div><small>OFFICIAL TOURNAMENT CENTER</small><h1>ฟุตบอลเฉลิมพระเกียรติ</h1><p>ครั้งที่ 13/2569 • {{s.division.name}}</p></div><select v-model="s.divisionKey" @change="s.setDivision(s.divisionKey)"><option value="PUBLIC">รุ่นประชาชน</option><option value="SENIOR40">รุ่นอาวุโส 40+</option></select></header><main class="public-content"><section><div class="section-title"><h2>ผลแบ่งสาย</h2><span>LIVE</span></div><div class="group-grid"><GroupCard name="A" :teams="s.groups.A"/><GroupCard name="B" :teams="s.groups.B"/><GroupCard name="C" :teams="s.groups.C"/><GroupCard name="D" :teams="s.groups.D"/></div></section><section><div class="section-title"><h2>ผลการแข่งขันล่าสุด</h2></div><div class="score-cards"><article v-for="m in s.matches.filter(x=>x.status==='FINISHED').slice(-6).reverse()" :key="m.id"><small>{{m.stage}} {{m.group?'• สาย '+m.group:''}}</small><div><b>{{m.home.name}}</b><strong>{{m.homeScore}} - {{m.awayScore}}</strong><b>{{m.away.name}}</b></div></article><p v-if="!s.matches.some(x=>x.status==='FINISHED')" class="muted">ยังไม่มีผลการแข่งขัน</p></div></section></main></div></template>
